-- PostgreSQL. Cloud: database da duoc nha cung cap tao san, chon qua DATABASE_URL.
-- Khong dung CREATE DATABASE o day.
-- Thay doi cau truc ve sau: viet thanh file trong db/migrations/ (001_..., 002_...).
--
-- Chuyen tu MySQL sang PostgreSQL theo SRS muc 4 (dich la Supabase):
--   INT UNSIGNED AUTO_INCREMENT -> INT GENERATED BY DEFAULT AS IDENTITY
--     (BY DEFAULT chu khong ALWAYS, vi seed/migrations co INSERT kem id tuong minh)
--   ENUM(...)                   -> VARCHAR + CHECK (Postgres khong co ENUM inline,
--                                  va CREATE TYPE khong ho tro IF NOT EXISTS)
--   DATETIME                    -> TIMESTAMPTZ (bo duoc hack timezone '+07:00')
--   ON UPDATE CURRENT_TIMESTAMP -> trigger set_updated_at() o cuoi file
--   UNIQUE KEY / KEY            -> UNIQUE constraint / CREATE INDEX

-- Im cac NOTICE cua DROP ... IF EXISTS khi chay tren DB trang.
SET client_min_messages = warning;

-- 0. Ham dung chung cho cac trigger updated_at --------------------------
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- 1. users ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  user_id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name          VARCHAR(100) NOT NULL,
  email              VARCHAR(255) NOT NULL,
  password_hash      VARCHAR(255) NULL,
  auth_provider      VARCHAR(10) NOT NULL
                     CHECK (auth_provider IN ('LOCAL', 'GOOGLE')),
  user_role          VARCHAR(10) NOT NULL
                     CHECK (user_role IN ('admin','tester','dev','viewer')),
  user_status        VARCHAR(10) NOT NULL DEFAULT 'active'
                     CHECK (user_status IN ('active','inactive')),
  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_users_email UNIQUE (email)
);


-- 2. test_suites ------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_suites (
  suite_id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  suite_name         VARCHAR(150) NOT NULL,
  suite_description  TEXT NULL,
  created_by         INT NULL,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by         INT NULL,
  updated_at         TIMESTAMPTZ NULL DEFAULT NULL,
  CONSTRAINT fk_suites_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE SET NULL,
  CONSTRAINT fk_suites_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id) ON DELETE SET NULL
);


-- 3. test_specs -------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_specs (
  spec_id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  spec_code          VARCHAR(30) NOT NULL,
  suite_id           INT NOT NULL,
  source_reference   VARCHAR(255) NULL,
  screen_name        VARCHAR(255) NULL,
  spec_description   TEXT NULL,
  created_by         INT NULL,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by         INT NULL,
  updated_at         TIMESTAMPTZ NULL DEFAULT NULL,
  CONSTRAINT uq_specs_spec_code UNIQUE (spec_code),
  CONSTRAINT fk_specs_suite
    FOREIGN KEY (suite_id) REFERENCES test_suites(suite_id) ON DELETE RESTRICT,
  CONSTRAINT fk_specs_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE SET NULL,
  CONSTRAINT fk_specs_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id) ON DELETE SET NULL
);


-- 4. test_cases -------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_cases (
  test_id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  spec_id            INT NOT NULL,
  tc_code            VARCHAR(30) NOT NULL,
  title              VARCHAR(255) NOT NULL,
  preconditions      TEXT NULL,
  expected_result    TEXT NOT NULL,
  priority           VARCHAR(10) NOT NULL
                     CHECK (priority IN ('low','medium','high','critical')),
  test_type          VARCHAR(15) NOT NULL
                     CHECK (test_type IN ('functional','ui','validation','security','performance','usability','audit')),
  test_status        VARCHAR(10) NOT NULL DEFAULT 'draft'
                     CHECK (test_status IN ('draft','ready','deprecated')),
  automation_ref     VARCHAR(255) NULL,
  created_by         INT NULL,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by         INT NULL,
  updated_at         TIMESTAMPTZ NULL DEFAULT NULL,
  CONSTRAINT uq_cases_tc_code UNIQUE (tc_code),
  CONSTRAINT uq_cases_automation_ref UNIQUE (automation_ref),
  CONSTRAINT fk_cases_spec
    FOREIGN KEY (spec_id) REFERENCES test_specs(spec_id) ON DELETE RESTRICT,
  CONSTRAINT fk_cases_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE SET NULL,
  CONSTRAINT fk_cases_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id) ON DELETE SET NULL
);


-- 5. test_steps -------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_steps (
  step_id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  test_id            INT NOT NULL,
  step_order         INT NOT NULL,
  step_action        TEXT NOT NULL,
  step_target        VARCHAR(255) NULL,
  expected_result    TEXT NULL,
  CONSTRAINT uq_steps_order UNIQUE (test_id, step_order),
  CONSTRAINT fk_steps_case
    FOREIGN KEY (test_id) REFERENCES test_cases(test_id) ON DELETE CASCADE
);


-- 6. test_data --------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_data (
  data_id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  test_id            INT NOT NULL,
  field_name         VARCHAR(100) NOT NULL,
  data_value         TEXT NULL,
  is_valid           BOOLEAN NOT NULL,
  CONSTRAINT fk_data_case
    FOREIGN KEY (test_id) REFERENCES test_cases(test_id) ON DELETE CASCADE
);


-- 7. test_runs --------------------------------------------------------
CREATE TABLE IF NOT EXISTS test_runs (
  run_id             INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  started_at         TIMESTAMPTZ NOT NULL,
  finished_at        TIMESTAMPTZ NULL,
  browser            VARCHAR(50) NOT NULL,
  environment        VARCHAR(100) NULL,
  git_commit         VARCHAR(64) NULL,
  branch_name        VARCHAR(100) NULL,
  ci_run_id          VARCHAR(100) NULL,

  -- user thuc hien lan chay test
  tester_id          INT NULL,

  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_test_runs_tester
    FOREIGN KEY (tester_id) REFERENCES users(user_id) ON DELETE SET NULL
);


-- 8. test_results -----------------------------------------------------
CREATE TABLE IF NOT EXISTS test_results (
  execution_id       INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id             INT NOT NULL,
  test_id            INT NOT NULL,
  result_status      VARCHAR(12) NOT NULL
                     CHECK (result_status IN ('passed','failed','timedOut','skipped','interrupted')),

  -- ket qua thuc te cua test case
  actual_result      TEXT NULL,

  execution_time_ms  INT NOT NULL DEFAULT 0,
  error_message      TEXT NULL,
  retry_count        INT NOT NULL DEFAULT 0,
  CONSTRAINT fk_results_run
    FOREIGN KEY (run_id) REFERENCES test_runs(run_id) ON DELETE CASCADE,
  CONSTRAINT fk_results_case
    FOREIGN KEY (test_id) REFERENCES test_cases(test_id) ON DELETE CASCADE
);


-- 9. test_evidences ---------------------------------------------------
CREATE TABLE IF NOT EXISTS test_evidences (
  evidence_id        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  result_id          INT NOT NULL,
  evidence_type      VARCHAR(10) NOT NULL
                     CHECK (evidence_type IN ('screenshot','trace')),
  file_path          VARCHAR(500) NOT NULL,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_evidences_result
    FOREIGN KEY (result_id) REFERENCES test_results(execution_id) ON DELETE CASCADE
);


-- 11. reports ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS reports (
  report_id      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id         INT NOT NULL,
  report_type    VARCHAR(5) NOT NULL DEFAULT 'pdf'
                 CHECK (report_type IN ('pdf')),
  file_path      VARCHAR(500) NOT NULL,
  generated_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  generated_by   INT NULL,

  CONSTRAINT fk_reports_run
    FOREIGN KEY (run_id)
    REFERENCES test_runs(run_id)
    ON DELETE CASCADE,

  CONSTRAINT fk_reports_generated_by
    FOREIGN KEY (generated_by)
    REFERENCES users(user_id)
    ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_reports_run_id ON reports (run_id);


-- 12. Trigger updated_at ----------------------------------------------
-- Thay cho ON UPDATE CURRENT_TIMESTAMP cua MySQL. Chi 3 bang co cot updated_at.
DROP TRIGGER IF EXISTS trg_suites_updated_at ON test_suites;
CREATE TRIGGER trg_suites_updated_at BEFORE UPDATE ON test_suites
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_specs_updated_at ON test_specs;
CREATE TRIGGER trg_specs_updated_at BEFORE UPDATE ON test_specs
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_cases_updated_at ON test_cases;
CREATE TRIGGER trg_cases_updated_at BEFORE UPDATE ON test_cases
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

